def products_for_industry_detail(slug):
    # Backed by atlasco.industry.product (editable in the backend under
    # Website > Configuration > Atlasco Website > Industry Products) — one
    # row per (industry, product), so every industry has its own images.
    return request.env['atlasco.industry.product'].sudo().search(
        [('industry_slug', '=', slug)])


