def rich_product_page(industry_slug, product_slug):
    return _RICH_BY_INDUSTRY.get(industry_slug, {}).get(product_slug)


def industry_product_cards(industry_slug, product_slug):
    """Return list of detail cards for (industry, product). May be empty."""
    # Oil & Gas gas-generation has deep adjusted-PDF data
    if industry_slug == 'oil-gas' and product_slug == 'gas-generation':
        return _OILGAS_GAS_GENERATION_CARDS
    detail = INDUSTRY_PRODUCT_DETAILS.get(industry_slug)
    if not detail:
        return []
    keywords = _PRODUCT_CARD_KEYWORDS.get(product_slug, [])
    if not keywords:
        return []
    return [c for c in detail['cards'] if any(kw in c['title'] for kw in keywords)]


def hero_copy_for_industry(slug):
    return INDUSTRY_HERO_COPY.get(slug)


def reliability_for_industry(slug):
    return INDUSTRY_RELIABILITY.get(slug)


