def _wire_product_imagery():
    for slug, cat in PRODUCT_CATEGORIES.items():
        if slug in _CATEGORY_BANNERS:
            cat['banner'] = _CATEGORY_BANNERS[slug]
        if slug in _CATEGORY_ICONS:
            cat['icon'] = _CATEGORY_ICONS[slug]
        photos = _PRODUCT_PHOTOS.get(slug, {})
        for item in cat.get('items', []):
            fname = photos.get(item['slug'])
            if fname:
                item['image'] = _PP + fname
            # Per-product L3 detail-page hero banner (877x269), if the client
            # supplied one for this item.
            l3banner = _L3_BANNERS.get(item['slug'])
            if l3banner:
                item['banner'] = l3banner


_wire_product_imagery()


def _product_catalog_image(url):
    """Best-effort banner/photo lookup for a /products/<cat>[/<leaf>] url —
    used to give a partner's Product Range tile a real image even when no
    partner-specific photo was uploaded (atlasco.partner.product.image is
    optional and, for the 23 legacy partners, always empty)."""
    if not url:
        return ''
    parts = [p for p in url.split('/') if p]
    if len(parts) < 2 or parts[0] != 'products':
        return ''
    cat = PRODUCT_CATEGORIES.get(parts[1])
    if not cat:
        return ''
    if len(parts) > 2:
        leaf = next((it for it in cat.get('items', []) if it['slug'] == parts[2]), None)
        if leaf:
            return leaf.get('banner') or leaf.get('image') or cat.get('banner', '')
        return ''
    return cat.get('banner', '')


def _service_catalog_image(url, env=None):
    """Same idea as _product_catalog_image, but for partner Product Range
    tiles whose linked url is a /services/<slug> page (several partners'
    "products" are actually services — e.g. SPM/SDT/IRISS -> condition
    monitoring, Noria/Mobius/ITC -> PrimeGear training).

    `env` lets this be called outside an HTTP request (e.g. from a
    <function> data-file seed at module install/upgrade, where the global
    `request` proxy is unbound and raises RuntimeError) — every normal
    page-render call site omits it and falls back to `request.env` as
    before.
    """
    if not url:
        return ''
    parts = [p for p in url.split('/') if p]
    if len(parts) != 2 or parts[0] != 'services':
        return ''
    env = env if env is not None else request.env
    rec = env['atlasco.service'].sudo().search([('slug', '=', parts[1])], limit=1)
    if rec and rec.hero_image:
        return '/web/image/atlasco.service/%d/hero_image' % rec.id
    return ''


