    @http.route('/industries/<string:industry>', type='http', auth='public', website=True)
    def industry_detail(self, industry, **kwargs):
        industries = {
            'oil-gas': {
                'name': 'Oil & Gas Industry',
                'subtitle': 'Atlasco Egypt delivers advanced air and reliability solutions for the toughest oil & gas environments—ensuring safe and uninterrupted operations.',
                'slug': 'oil-gas',
            },
            'pharmaceutical': {
                'name': 'Pharmaceutical Industry',
                'subtitle': 'ISO-certified Class II clean air solutions for pharmaceutical manufacturing excellence.',
                'slug': 'pharmaceutical',
            },
            'medical': {
                'name': 'Medical Industry',
                'subtitle': 'Medical grade oxygen and vacuum systems for life-critical environments.',
                'slug': 'medical',
            },
            'steel': {
                'name': 'Steel Industry',
                'subtitle': 'High-pressure compressed air systems purpose-built for steel manufacturing.',
                'slug': 'steel',
            },
            'food-beverage': {
                'name': 'Food & Beverage Industry',
                'subtitle': 'Hygienic compressed air for processing lines in food and beverage production.',
                'slug': 'food-beverage',
            },
            'power-generation': {
                'name': 'Power Generation Industry',
                'subtitle': 'High-pressure systems for turbine cooling and power generation facilities.',
                'slug': 'power-generation',
            },
            'textile': {
                'name': 'Textile Industry',
                'subtitle': 'Compressed air, blowers, and condition-monitoring solutions for textile mills.',
                'slug': 'textile',
            },
            'electronics': {
                'name': 'Electronics Industry',
                'subtitle': 'Clean, oil-free air and high-purity gas systems for electronics manufacturing.',
                'slug': 'electronics',
            },
            'cement': {
                'name': 'Cement Industry',
                'subtitle': 'Heavy-duty compressed air, vacuum, and dust-collection systems for cement plants.',
                'slug': 'cement',
            },
            'construction': {
                'name': 'Construction Industry',
                'subtitle': 'Portable compressors, generators, and on-site equipment for construction sites.',
                'slug': 'construction',
            },
        }
        data = industries.get(industry, industries['oil-gas'])
        # atlasco.home.industry already holds an editable image per industry
        # (used on the homepage grid); reuse it here so "Related Industries"
        # shows the same real photo and stays editable from the live page.
        home_industry_by_slug = {
            rec.href.rsplit('/', 1)[-1]: rec
            for rec in request.env['atlasco.home.industry'].sudo().search([])
            if rec.href
        }
        current_home_industry = home_industry_by_slug.get(data['slug'])
        curated = current_home_industry.related_industry_ids if current_home_industry else None
        if curated:
            related_industries = []
            for rec in curated.sorted(key=lambda r: (r.sequence, r.id)):
                slug = rec.href.rsplit('/', 1)[-1] if rec.href else False
                info = industries.get(slug)
                if not info:
                    continue
                related_industries.append({
                    'slug': slug, 'name': info['name'].replace(' Industry', ''),
                    'desc': info['subtitle'], 'home_industry': rec,
                })
        else:
            # Default for industries with no curated picks: first 5 others.
            related_industries = [
                {'slug': s, 'name': industries[s]['name'].replace(' Industry', ''),
                 'desc': industries[s]['subtitle'],
                 'home_industry': home_industry_by_slug.get(s)}
                for s in industries.keys() if s != data['slug']
            ][:5]
        return request.render('atlasco_website.industry_detail', {
            'industry': data,
            'hero_copy': hero_copy_for_industry(data['slug']),
            'reliability': reliability_for_industry(data['slug']),
            'reliability_cards': request.env['atlasco.reliability.card'].sudo().search([('industry_slug', '=', data['slug'])], order='sequence, id'),
            'industry_products': products_for_industry_detail(data['slug']),
            'product_details': product_details_for_industry(data['slug']),
            'partners': partners_for_industry(data['slug']),
            'related_industries': related_industries,
            'additional_title': data['name'],
        })

    @http.route('/industries/<string:industry>/<string:product>', type='http', auth='public', website=True)
    def industry_product_detail(self, industry, product, **kwargs):
        # 404 if product not in this industry's allowed product list
        # (e.g. gas-generation has no source data for non-OG industries)
        allowed = products_for_industry_detail(industry)
        product_match = next((p for p in allowed if p['slug'] == product), None)
        if not product_match:
            return request.not_found()
        if not hero_copy_for_industry(industry):
            # also accept industries that have no hero copy yet (e.g. cement) — render anyway with slug-based name
            pass
        industry_name_map = {
            'oil-gas': 'Oil & Gas', 'steel': 'Steel', 'pharmaceutical': 'Pharmaceutical',
            'medical': 'Medical', 'food-beverage': 'Food & Beverage', 'textile': 'Textile',
            'electronics': 'Electronics', 'cement': 'Cement', 'construction': 'Construction',
        }
        industry_name = industry_name_map.get(industry, industry.replace('-', ' ').title())
        return request.render('atlasco_website.industry_product_detail', {
            'industry_slug': industry,
            'industry_name': industry_name,
            'product': product_match,
            'cards': industry_product_cards(industry, product),
            'rich': rich_product_page(industry, product),
            'additional_title': '%s - %s' % (product_match.name, industry_name),
        })

    # ClickUp 869f082c8: services used to be a hardcoded dict here (7 entries,
    # no way to add an 8th without a code change). They are now real
    # atlasco.service records — see models/atlasco_service.py — edited under
    # Website > Content > Services. This helper keeps the existing dict shape
    # ({'slug', 'name', 'subtitle', 'intro', 'sub_offerings': [...],
    # 'hero_image'}) so the existing templates (views/services.xml,
    # views/arms.xml) don't need to change how they read the data.
    @staticmethod
    def _service_to_dict(rec):
        _SVC_IMG_BASE = '/atlasco_website/static/src/img/services/'
        _SVC_FS_BASE = os.path.join(os.path.dirname(__file__), '..', 'static', 'src', 'img', 'services')
        if rec.hero_image:
            hero_image = '/web/image/atlasco.service/%d/hero_image' % rec.id
        else:
            # Back-compat: a service that hasn't had its hero_image uploaded
            # yet (e.g. one just added in the backend) falls back to a
            # same-named static folder if one happens to exist.
            _hero_fs = os.path.join(_SVC_FS_BASE, rec.slug or '', 'hero.jpg')
            hero_image = (_SVC_IMG_BASE + rec.slug + '/hero.jpg') if os.path.exists(_hero_fs) else None
        return {
            'id': rec.id,
            'slug': rec.slug,
            'name': rec.name,
            'subtitle': rec.subtitle or '',
            'intro': rec.intro or '',
            'card_description': rec.card_description or rec.intro or '',
            'is_dark_panel': rec.is_dark_panel,
            'href': rec.href(),
            'hero_image': hero_image,
            'sub_offerings': [
                {'name': o.name, 'desc': o.desc or ''} for o in rec.offering_ids
            ],
        }

    @http.route('/services', type='http', auth='public', website=True)
    def services(self, **kwargs):
        records = request.env['atlasco.service'].sudo().search([], order='sequence, id')
        services_list = [self._service_to_dict(r) for r in records]
        return request.render('atlasco_website.services', {'services_list': services_list, 'additional_title': 'Services'})

    @http.route('/services/<string:service>', type='http', auth='public', website=True)
    def service_detail(self, service, **kwargs):
        # Legacy aliases — redirect old slugs to current ones
        aliases = {
            'arms': 'condition-monitoring',
            'installation-commissioning': 'piping-installation',
            'piping-system-integration': 'piping-installation',
        }
        service = aliases.get(service, service)
        process_steps = [
            {'step': '1', 'name': 'Assess', 'desc': 'On-site baseline assessment of all critical rotary and electrical assets.'},
            {'step': '2', 'name': 'Diagnose', 'desc': 'Data interpretation using specialized AI and engineering expertise.'},
            {'step': '3', 'name': 'Implementation', 'desc': 'Precise alignment, lubrication, and correction of identified faults.'},
            {'step': '4', 'name': 'Monitor', 'desc': 'Continuous remote monitoring and scheduled periodic site check-ups.'},
        ]
        Service = request.env['atlasco.service'].sudo()
        rec = Service.search([('slug', '=', service)], limit=1)
        if not rec:
            # Preserve the previous fallback behavior (unknown/legacy slugs
            # rendered the first service rather than 404ing) rather than
            # changing site behavior as a side effect of this fix.
            rec = Service.search([], order='sequence, id', limit=1)
        if not rec:
            return request.not_found()
        data = self._service_to_dict(rec)
        services_index = {r.slug: self._service_to_dict(r) for r in Service.search([], order='sequence, id')}
        return request.render('atlasco_website.service_detail', {
            'service': data, 'process_steps': process_steps, 'services_index': services_index,
            'additional_title': data['name'],
        })

