    def _get_open_positions(self):
        # hr.job is now the source of truth for "Current Openings" (previously
        # atlasco.career.opening, which stays installed/dormant for rollback -
        # see AtlascoCareerOpening in models/content_careers.py). Built as plain
        # dicts rather than passing hr.job recordsets straight to the template
        # so the QWEB side doesn't need to know about website_description
        # being Html (stripped to plain text here for the card blurb) or
        # requirements being a raw newline-separated Text field.
        jobs = request.env['hr.job'].sudo().search(
            [('website_published', '=', True)], order='sequence, name asc')
        openings = []
        for job in jobs:
            department = job.department_id.name or ''
            location = job.address_id.city or job.address_id.name or ''
            blurb = html2plaintext(job.website_description or '').strip()
            points = [p.strip() for p in (job.requirements or '').split('\n') if p.strip()]
            # Same "don't show a blank-looking card" rule the old model used
            # (see BUG-06 comment in atlasco_careers_page.xml).
            if not (department or blurb or points):
                continue
            openings.append({
                'id': job.id,
                'title': job.name,
                'department': department,
                'location': location,
                'job_type': job.contract_type_id.name or '',
                'blurb': blurb,
                'points': points,
            })
        return openings

    @http.route('/careers', type='http', auth='public', website=True)
    def careers(self, **kwargs):
        content = request.env['atlasco.content'].sudo()._get()
        openings = self._get_open_positions()
        error = {}
        default = {}
        if 'careers_apply_error' in request.session:
            error = request.session.pop('careers_apply_error')
            default = request.session.pop('careers_apply_default')
        return request.render('atlasco_website.careers', {
            'content': content,
            'careers_openings': openings,
            'careers_departments': sorted({o['department'] for o in openings if o['department']}),
            'careers_locations': sorted({o['location'] for o in openings if o['location']}),
            'careers_apply_error': error,
            'careers_apply_default': default,
            'careers_apply_submitted': request.session.pop('careers_apply_submitted', False),
            'additional_title': 'Careers',
        })

    @http.route('/careers/apply', type='http', auth='public', website=True, methods=['POST'], csrf=True)
    def careers_apply_submit(self, **kwargs):
        # A dedicated route rather than Odoo's generic /website/form/<model>
        # endpoint: that endpoint always answers with a raw JSON body, meant
        # to be consumed by the s_website_form JS widget (which expects the
        # form's fields wrapped in its own s_website_form_field/_input class
        # structure). Retrofitting that onto the existing hand-built
        # .crb-form markup would mean restructuring it - out of scope per
        # "do not redesign the Careers page". This route still targets
        # hr.applicant directly (no new model), same pattern already
        # approved for the /contact/submit -> crm.lead flow.
        values = {
            'full_name': (kwargs.get('full_name') or '').strip(),
            'email': (kwargs.get('email') or '').strip(),
            'phone': (kwargs.get('phone') or '').strip(),
            'linkedin': (kwargs.get('linkedin') or '').strip(),
            'message': (kwargs.get('message') or '').strip(),
            'job_id': kwargs.get('job_id') or '',
            'job_title': (kwargs.get('job_title') or '').strip(),
        }

        error = None
        if not values['full_name']:
            error = "Please enter your full name."
        elif not values['email']:
            error = "Please enter your email address."
        elif not email_split(values['email']):
            error = "Please enter a valid email address."

        job = None
        if values['job_id']:
            job = request.env['hr.job'].sudo().browse(int(values['job_id']))
            if not job.exists() or not job.website_published:
                job = None

        if error:
            request.session['careers_apply_error'] = error
            request.session['careers_apply_default'] = values
            return request.redirect('/careers#apply')

        try:
            request.env['hr.applicant'].sudo().create({
                'name': 'Website Application: %s' % values['full_name'],
                'partner_name': values['full_name'],
                'email_from': values['email'],
                'partner_phone': values['phone'] or False,
                'linkedin_profile': values['linkedin'] or False,
                'description': values['message'] or False,
                'job_id': job.id if job else False,
            })
        except Exception:
            _logger.exception("Failed to record career application (hr.applicant)")
            request.session['careers_apply_error'] = (
                "Sorry, something went wrong while sending your application. Please try again or "
                "email your CV to careers@atlascoegypt.com.")
            request.session['careers_apply_default'] = values
            return request.redirect('/careers#apply')

        request.session['careers_apply_submitted'] = True
        return request.redirect('/careers#apply')

    # (model, field) pairs the "Replace video" snippet option (AtlascoVideoReplace,
    # static/src/js/atlasco_video_option.js) is actually wired to - see the
    # data-video-model/id/field attributes in atlasco_about_page.xml,
    # atlasco_careers_page.xml, and atlasco_culture_page.xml. Whitelisted here
    # so this upload route can't be pointed at an arbitrary model/field by a
    # crafted request.
    _VIDEO_UPLOAD_TARGETS = {
        ('atlasco.content', 'about_video_src'),
        ('atlasco.content', 'careers_hero_video'),
        ('atlasco.culture.life', 'vsrc'),
    }

    # Odoo's own http layer caps every request at 128MB by default
    # (odoo/http.py DEFAULT_MAX_CONTENT_LENGTH) - independent of any nginx/
    # proxy limit, and the actual reason a 300MB+ video upload was failing
    # even with a proper multipart upload. Raised here, for this route only,
    # rather than touching that global default.
    @http.route('/atlasco_website/video/upload', type='http', auth='user', website=True,
                methods=['POST'], csrf=True, max_content_length=512 * 1024 * 1024)
    def atlasco_video_upload(self, **kwargs):
        # Odoo's own web_editor upload (/web_editor/attachment/add_data, used
        # by the Media Dialog) is JSON-RPC: the browser has to base64-encode
        # the WHOLE file into one JSON body first. That's fine for images,
        # but for a many-hundred-MB video it means holding a ~33% larger
        # base64 string in the tab's memory and one giant JSON POST - exactly
        # the kind of upload that hangs or fails outright, which is what someone
        # hit trying to replace a culture-page video. A plain multipart
        # file upload (this route) streams the file instead, so the browser
        # never has to buffer the whole thing as a JSON string. Real server
        # limits (nginx client_max_body_size, proxy timeouts) still apply on
        # top of this and are outside what a code change can fix.
        upload = request.httprequest.files.get('file')
        model = kwargs.get('model')
        field = kwargs.get('field')
        try:
            res_id = int(kwargs.get('res_id') or 0)
        except ValueError:
            res_id = 0

        if not upload or not res_id or (model, field) not in self._VIDEO_UPLOAD_TARGETS:
            return request.make_json_response({'error': "Invalid upload request."}, status=400)
        if not (upload.mimetype or '').startswith('video/'):
            return request.make_json_response({'error': "Please choose a video file."}, status=400)

        try:
            attachment = request.env['ir.attachment'].sudo().create({
                'name': upload.filename,
                'datas': base64.b64encode(upload.read()),
                'res_model': model,
                'res_id': res_id,
                'mimetype': upload.mimetype,
                'public': True,
            })
            url = '/web/content/%d?unique=%s' % (attachment.id, int(attachment.write_date.timestamp()))
            request.env[model].sudo().browse(res_id).write({field: url})
        except Exception:
            _logger.exception("Failed to upload replacement video (model=%s field=%s)", model, field)
            return request.make_json_response(
                {'error': "Upload failed. The file may be too large for this server."}, status=500)

        return request.make_json_response({'url': url})

